from pathlib import Path
import html
root=Path('docs/homepage-refinement/phase-11a5')
header='''<!doctype html><html lang="en"><meta charset="utf-8"><meta name="viewport" content="width=device-width,initial-scale=1"><title>Zieve photography — final selection review</title><style>*{box-sizing:border-box}body{margin:0;background:#f5f7f8;color:#0b2233;font:16px/1.7 Georgia,serif}main{max-width:1280px;margin:auto;padding:32px 20px}h1{font-size:clamp(2rem,4vw,3.5rem);line-height:1.15}h2{margin-top:3rem}a{color:inherit}img{display:block;max-width:100%}.crops{display:grid;grid-template-columns:3fr 1fr;gap:20px;align-items:start}.crop{position:relative;overflow:hidden;isolation:isolate;background:#0b2233}.crop img{width:100%;height:100%;object-fit:cover;object-position:70% 50%}.landscape{aspect-ratio:16/9}.portrait{aspect-ratio:390/844}.crop:after{content:"";position:absolute;inset:0;background:linear-gradient(90deg,#0b2233,rgba(11,34,51,.85) 45%,rgba(11,34,51,.4)),linear-gradient(0deg,#0b2233,transparent 50%)}.copy{position:absolute;z-index:2;left:5%;top:22%;max-width:62%;color:white;line-height:1.2;font-weight:bold;font-size:clamp(20px,3vw,44px)}.copy span{display:block;color:#f2a21a}.portrait .copy{font-size:20px;top:25%;max-width:85%}.caption{font-size:14px;padding-top:8px}.pair{display:grid;grid-template-columns:1fr 1fr;gap:20px}.pair img{width:100%;aspect-ratio:16/10;object-fit:cover}.note{border-left:3px solid #f2a21a;padding-left:16px}@media(max-width:640px){.crops,.pair{grid-template-columns:1fr}.portrait{max-width:390px}.landscape .copy{font-size:25px}.portrait .copy{font-size:36px}}</style><main><h1>Final photography selection</h1><p class="note">Standalone crop studies, not homepage integration. The live PH01 hero remains the original labelled schematic. Both replacements require final visual approval. Brand typography, layout and motion in the website are unchanged.</p>'''
body=''
for id,name,file,source,detail in [
 ('R1','Sunrise silhouette — Metehan Özaras','hero-R1-desktop.jpg','https://www.pexels.com/photo/silhouette-of-excavator-at-sunrise-11562423/','3648 × 2736 native. Unbranded distant excavator at sunrise. Proposed landscape crop: left 0, top 650, width 2600, height 1463. Machine/sun weighted right with quieter left sky. Restrained, scenic direction; machinery is small rather than an equipment close-up. Mobile uses this proposed review crop at 70% 50% and loses side terrain, not the subject. Tiny silhouettes are not identifiable. No mirroring.'),
 ('R2','Mining shovel at dusk — saravut vanset','hero-R2-desktop.jpg','https://www.pexels.com/photo/yellow-and-black-heavy-equipment-at-the-site-during-sunset-10410019/','5520 × 3680 native. Strong mining scale and equipment detail, no prominent manufacturer wordmark observed. The source is LEFT weighted: this study explicitly proposes horizontal reflection to place machinery RIGHT and sky LEFT. Modification is allowed by the Pexels licence, but this creative alteration needs approval. Do not use if mirrored engineering details are unacceptable. Narrow crop retains the machine body/track mass, losing parts of the extended bucket/boom. Small distant worker is not identifiable; no company ownership claim.')]:
 body+=f'<section><h2>{id} · {name}</h2><p>{detail}</p><p><a href="{source}">Original publisher and download</a> · <a href="https://www.pexels.com/license/">Pexels licence</a> · <a href="https://www.pexels.com/terms-of-service/">Detailed terms §5–6</a></p><div class="crops"><div><div class="crop landscape"><img src="previews/final-selection/{file}" alt="{html.escape(name)}"><div class="copy">Equipping Industry.<span>Empowering Growth.</span></div></div><p class="caption">Desktop 16:9 crop/overlay study</p></div><div><div class="crop portrait"><img src="previews/final-selection/{file}" alt="{html.escape(name)}"><div class="copy">Equipping Industry.<span>Empowering Growth.</span></div></div><p class="caption">Mobile 390:844 crop/overlay study</p></div></div></section>'
body+='''<section><h2>PH07 — final comparison</h2><div class="pair"><figure><img src="previews/spares-new.jpg" alt="Existing reflective fittings candidate"><figcaption>Original PH07 · shraga kopstein / Unsplash. Accurate subject, but warm/green specular reflections and crowded composition compete with the section.</figcaption></figure><figure><img src="previews/final-selection/spares-neutral.jpg" alt="Neutral silver nuts and bolts alternative"><figcaption>Selected PH07-B · Edge2Edge Media / Unsplash. Cleaner silver/white palette, clear central fastener and less distracting colour. Native 4093 × 2724. This depicts generic fasteners, not Zieve inventory or stock availability.</figcaption></figure></div><p><a href="https://unsplash.com/photos/a-pile-of-metal-fittings-and-nuts-991G3BcfXLs">Original PH07 source</a> · <a href="https://unsplash.com/photos/silver-and-black-metal-tools-qHhJkxare7A">Selected PH07-B source</a> · <a href="https://unsplash.com/license">Unsplash licence</a></p></section><p>PH02/PH05/PH07-B/PH08/PH10/PH11 integrated conditionally. PH03 and PH09 remain schematic because source-specific rights conditions are unresolved. PH04/PH06 retained by instruction. See the selection, rights and integration registers for details.</p></main></html>'''
(root/'FINAL_SELECTION_BOARD.html').write_text(header+body)
